import React from 'react';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { _ColumnOrderControls as ColumnOrderControls } from './ColumnOrderSettings/_ColumnOrderControls.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Text } from '../../../typography/Text.js';
import { ColumnMinInstance } from '../../types/internal-table-types.js';

type ColumnListItemProps = {
  column: ColumnMinInstance;
  columnCheckbox?: React.ReactElement;
  columnOrderSettings: boolean;
  configuredColumns: ColumnMinInstance[];
  onColumnsReordering: React.Dispatch<React.SetStateAction<unknown[]>>;
};

export const ColumnListItem = (props: ColumnListItemProps) => {
  const {
    column,
    columnCheckbox,
    columnOrderSettings,
    configuredColumns,
    onColumnsReordering,
  } = props;

  const isSubColumn = column.parent ? true : false;
  const level = isSubColumn ? 1 : 0;

  return (
    <Flex
      flexDirection={'row'}
      alignItems={'center'}
      style={{
        paddingLeft: `calc(${level} * ${Spacings.Size12} + ${Spacings.Size8})`,
        paddingRight: Spacings.Size8,
        gap: Spacings.Size16,
        minHeight: Spacings.Size32,
      }}
    >
      {columnCheckbox || (
        <Text textStyle="base" data-testid={'text'}>
          {column.Header as string}
        </Text>
      )}
      {columnOrderSettings && (
        <ColumnOrderControls
          style={{ marginLeft: 'auto' }}
          column={column}
          columns={configuredColumns}
          onColumnsReordering={onColumnsReordering}
        />
      )}
    </Flex>
  );
};
